  function effectSummary(effects){const labels={power:"قدرت",agility:"چابکی",endurance:"استقامت",vitality:"سرزندگی",intellect:"هوش",perception:"ادراک",luck:"شانس",faith:"ایمان",defense:"دفاع",hp:"سلامتی",mp:"مانا",stamina:"استقامت حرکتی",crit:"شانس ضربه بحرانی"};return Object.entries(effects||{}).map(([k,v])=>(labels[k]||k)+" +"+v).join(" • ");}
  function ensureGearState(item){if(!item)return item;if(!Number.isFinite(item.durability))item.durability=100;if(!Number.isFinite(item.maxDurability))item.maxDurability=100;if(!Number.isFinite(item.upgradeLevel))item.upgradeLevel=0;return item;}
