  function equipInventoryItem(itemId){const item=state.inventory.find(x=>x.id===itemId&&x.qty>0&&x.slot&&EQUIPMENT_SLOTS.some(s=>s[0]===x.slot));if(!item)return {ok:false,message:"این تجهیز در کیف موجود نیست یا جایگاه معتبری ندارد."};const requiredLevel=(item.itemLevel||1)<=1?1:(item.requiredPlayerLevel||5);if((state.character.level||1)<requiredLevel)return {ok:false,message:"سطح بازیکن برای پوشیدن این آیتم کافی نیست؛ سطح موردنیاز: "+requiredLevel+"."};state.equipmentSlots=state.equipmentSlots||{};const slot=item.slot,oldBonus=equipmentBonuses();if(state.equipmentSlots[slot])addInventoryItem({...state.equipmentSlots[slot],requiredPlayerLevel:1},1);item.qty--;if(item.qty<=0)state.inventory=state.inventory.filter(x=>x!==item);const equipped={...item,effects:{...(item.effects||{})},durability:100,maxDurability:100,upgradeLevel:0};delete equipped.qty;state.equipmentSlots[slot]=ensureGearState(equipped);const nextBonus=equipmentBonuses();state.character.mp=clamp((state.character.mp||0)+((nextBonus.mp+nextBonus.intellect*2+nextBonus.faith)-(oldBonus.mp+oldBonus.intellect*2+oldBonus.faith)),0,warriorMaxMp());state.character.stamina=clamp(state.character.stamina||0,0,warriorMaxStamina());journal("تجهیز "+equipped.name+" در جایگاه "+(EQUIPMENT_SLOTS.find(x=>x[0]===slot)?.[1]||slot)+"؛ آیتم قبلی به کیف بازگشت.");return {ok:true,message:equipped.name+" با موفقیت مجهز شد."};}
