  function deleteEquippedGear(slot){const item=state.equipmentSlots?.[slot];if(!item)return {ok:false,message:"این جایگاه خالی است."};const oldBonus=equipmentBonuses();delete state.equipmentSlots[slot];const nextBonus=equipmentBonuses();state.character.mp=clamp((state.character.mp||0)+((nextBonus.mp+nextBonus.intellect*2+nextBonus.faith)-(oldBonus.mp+oldBonus.intellect*2+oldBonus.faith)),0,warriorMaxMp());state.character.stamina=clamp(state.character.stamina||0,0,warriorMaxStamina());journal("تجهیز "+item.name+" از جایگاه "+(EQUIPMENT_SLOTS.find(x=>x[0]===slot)?.[1]||slot)+" برای همیشه حذف شد.");return {ok:true,message:item.name+" برای همیشه حذف شد."};}
