  function craftingView(){const known=knownRecipeIds(),current=state.character.archetype||"جنگجو",recipes=CLASS_CRAFTING_RECIPES.filter(r=>known.includes(r.id)&&r.className===current).sort((a,b)=>a.tier-b.tier);return '<section class="panel"><div class="sect"><b>کارگاه ساخت تجهیزات</b><small>۶۵۰ دستور ساخت اختصاصی • ۱۰ کلاس • ۱۳ اسلات تجهیز</small></div><p class="muted">هیولاها فقط مواد اولیه و گاهی دستور ساخت می‌اندازند. برای ساخت باید هم دستور همان آیتم و هم تمام مواد لازم را داشته باشی و آن‌ها را به آهنگر شهر خاکستر تحویل بدهی. آهنگر پس از ساخت، مواد و دستمزد را دریافت می‌کند و دستور یک‌بارمصرف از دفترت حذف می‌شود. فقط دستورهای مخصوص کلاس فعلی نمایش داده می‌شوند.</p><div class="row"><span>دستورهای کشف‌شده</span><b>'+known.length+' / ۶۵۰</b></div><div class="row"><span>کلاس فعال</span><b>'+esc(current)+'</b></div>'+recipes.map(r=>'<article style="border:1px solid #786746;background:#29252a;border-radius:12px;padding:12px;margin:9px 0"><b>'+esc(r.output.name)+'</b><small style="display:block;color:#d0bd91">'+esc(r.className)+' • '+r.slotLabel+' • سطح ساخت '+r.tier+'</small><p style="line-height:1.8;color:#c8bdab">'+esc(r.output.description)+'</p>'+r.materials.map(m=>'<div class="row"><span>'+REGION_MATERIALS[m.id].name+'<small style="display:block;color:#aebd9d">منبع: '+esc(REGION_MATERIALS[m.id].source)+'</small></span><b>'+materialInventoryCount(m.id)+' / '+m.qty+'</b></div>').join('')+'<div class="row"><span>هزینه ساخت</span><b>'+r.gold+' سکه</b></div><button type="button" data-craft-recipe="'+r.id+'" style="width:100%;min-height:46px">⚒ ساخت تجهیز</button></article>').join('')+(recipes.length?"":'<p class="muted">هنوز هیچ دستوری کشف نکرده‌ای. شکار هیولاها یا جست‌وجوی دانجن‌ها و خرابه‌ها را آغاز کن.</p>')+'</section>';}
