    const poly=worldRegistry.landmassGeometry.map(c=>'<g class="atlas-continent atlas-feature" data-atlas-feature="'+c.id+'" tabindex="0" role="button"><polygon points="'+c.points.map(xy).join(" ")+'"/><text x="'+c.anchor[0]+'" y="'+c.anchor[1]+'">'+esc(c.label)+'</text><title>'+esc(c.id)+'</title></g>').join("");
    const coasts=worldRegistry.landmassGeometry.map(c=>'<polyline class="coast-line" points="'+c.points.concat([c.points[0]]).map(xy).join(" ")+'"/>').join("");const coastMarks=worldRegistry.namedCoastalFeatures.map(c=>'<g class="atlas-feature coast-feature" data-atlas-feature="'+c.id+'" tabindex="0" role="button"><circle cx="'+c.point[0]+'" cy="'+c.point[1]+'" r="5"/><text x="'+(c.point[0]+8)+'" y="'+(c.point[1]-8)+'">'+esc(c.label)+'</text></g>').join("");
    const selected=selectedAtlasFeature?(()=>{const f=[...worldRegistry.continents,...worldRegistry.regions,...worldRegistry.regionGeometry,...worldRegistry.geographicRegions,...worldRegistry.namedCoastalFeatures,...worldRegistry.settlementFramework.settlements,...worldRegistry.naturalFeatures,...worldRegistry.seas,...worldRegistry.archipelagos,...worldRegistry.politicalGeography.polities,...worldRegistry.undergroundAtlas.layers,...worldRegistry.routeNetwork.routes,...worldRegistry.localAtlases,...regionalAtlasCatalog].find(x=>x.id===selectedAtlasFeature);return f?'<div class="atlas-feature-detail"><b>'+esc(f.label||f.name||f.role||f.id)+'</b><small>'+esc(f.role||f.kind||f.type||f.status||"عارضه جغرافیایی")+'</small><span>شناسه: '+esc(f.id)+'</span></div>':"";})():"";
    const water=worldRegistry.waterGeometry.map(w=>'<g class="atlas-water"><ellipse cx="'+w.anchor[0]+'" cy="'+w.anchor[1]+'" rx="'+Math.max(18,(w.bounds.maxX-w.bounds.minX)/2)+'" ry="'+Math.max(10,(w.bounds.maxY-w.bounds.minY)/2)+'"/><text x="'+w.anchor[0]+'" y="'+w.anchor[1]+'">'+esc(w.label)+'</text></g>').join("");
    const relief=worldRegistry.reliefGeometry.map(f=>'<g class="atlas-feature" data-atlas-feature="'+f.id+'" tabindex="0" role="button"><polyline points="'+f.points.map(xy).join(" ")+'" class="relief-line"/>'+((f.kind==="upland_area")?'<polygon points="'+f.points.map(xy).join(" ")+'" class="relief-area"/>':"")+'<text class="relief-label" x="'+f.points[0][0]+'" y="'+(f.points[0][1]-12)+'">'+esc(f.label||f.name||f.id)+'</text></g>').join("");
