    const lakes=worldRegistry.lakes.map(l=>'<g class="atlas-feature lake-feature" data-atlas-feature="'+l.id+'" tabindex="0" role="button"><ellipse cx="'+l.point[0]+'" cy="'+l.point[1]+'" rx="10" ry="6" class="lake-mark"/><text x="'+(l.point[0]+12)+'" y="'+(l.point[1]-8)+'">'+esc(l.label||l.name||"دریاچه")+'</text></g>').join("");
    const islands=worldRegistry.islandGeometry.map(g=>'<g class="island-mark atlas-feature" data-atlas-feature="'+g.id+'" tabindex="0" role="button"><ellipse cx="'+g.anchor[0]+'" cy="'+g.anchor[1]+'" rx="'+Math.max(8,(g.bounds.maxX-g.bounds.minX)/2)+'" ry="'+Math.max(5,(g.bounds.maxY-g.bounds.minY)/2)+'"/>'+g.majorIslandAnchors.map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="6"/>').join("")+'<text x="'+g.anchor[0]+'" y="'+(g.anchor[1]-18)+'">'+esc(g.label||g.name)+'</text></g>').join("");
    const continentPoints={continent_civilized:[235,235],continent_ancient:[475,155],continent_wild:[435,420],continent_arcane:[720,165],continent_far:[790,445]};
