    const pointById={"settlement_ash_city":[235,235],"settlement_west_harbor":[125,250],"settlement_river_candidate":[270,285],"settlement_ancient_outpost":[515,205],"settlement_wild_waystation":[425,385],"settlement_wild_spring_camp":[535,485],"settlement_arcane_watch":[685,135],"settlement_far_coast":[875,410],"settlement_wheat_village":[285,220],"settlement_crown_fort":[455,125],"settlement_saltworks":[550,235],"settlement_rootwood":[390,430],"settlement_ember_watch":[525,470],"settlement_star_shrine":[720,245],"settlement_mist_haven":[820,265],"settlement_cold_harbor":[900,380],"settlement_windhaven":[800,500],"settlement_last_camp":[925,520],"region_civilized_riverlands":[270,285],"region_ancient_high_table":[465,145],"region_ancient_riftlands":[515,205],"region_wild_mountain_forest":[425,385],"region_wild_volcanic_south":[535,485],"region_arcane_basalt":[685,135],"region_arcane_flux":[765,195],"region_far_outer_coast":[875,410],"region_far_extreme_interior":[800,485],"sea_inner":[500,285],"sea_north_broken":[480,28],"sea_west_shelf":[55,300]};const cp=pointById[state.currentWorldNode||mapNodeForCharacter()];const currentMarker=cp?'<g class="player-map-marker"><circle cx="'+cp[0]+'" cy="'+cp[1]+'" r="19"/><circle cx="'+cp[0]+'" cy="'+cp[1]+'" r="7"/><text x="'+(cp[0]+22)+'" y="'+(cp[1]-18)+'">موقعیت تو</text></g>':"";
    const routeLines=worldRegistry.routeNetwork.routes.map(r=>{const a=r.fromPoint||pointById[r.from]||pointById[r.fromId],b=r.toPoint||pointById[r.to]||pointById[r.toId];if(!a||!b)return "";const pts=r.pathPoints&&r.pathPoints.length>1?r.pathPoints:[a,b];const mid=pts[Math.floor(pts.length/2)];return '<g class="atlas-feature" data-atlas-feature="'+r.id+'" tabindex="0" role="button"><polyline class="route-mark" points="'+pts.map(xy).join(" ")+'"/><text class="route-label" x="'+mid[0]+'" y="'+(mid[1]-12)+'">'+esc(r.name||r.id)+'</text></g>';}).join("");
