  function communityEventForDay(){const day=state.worldClock?.day||1,events=[{zone:'grain',village:'روستای کشتزار',place:'میدان آسیاب',title:'جشن نان تازه',host:'اُلان آسیابان',desc:'اهالی کشتزار پس از آسیاب روزانه، نان‌های تازه را میان همسایه‌ها تقسیم می‌کنند. کودکان مسابقه چیدن خوشه‌ها برگزار کرده‌اند و نانوا داستان سال پربرکت گذشته را تعریف می‌کند.',dialogue:'اُلان می‌گوید: «نان وقتی خوش‌طعم‌تر می‌شود که با دیگران قسمت شود.»',reward:'bread',item:'نان روستایی',qty:1,xp:6,gold:3},{zone:'rootwood',village:'روستای ریشه‌چوب',place:'حیاط زنبورستان',title:'شب فانوس‌های جنگلی',host:'مِل زنبوردار',desc:'ساکنان ریشه‌چوب فانوس‌های کوچک با موم طبیعی می‌سازند و آن‌ها را در امتداد راه‌های روستا می‌آویزند. هیچ آتشی در جنگل روشن نمی‌شود و همه چراغ‌ها ایمن و محافظت‌شده‌اند.',dialogue:'مِل می‌گوید: «نورهای کوچک، راه خانه را برای همه روشن می‌کنند.»',reward:'beeswax',item:'موم زنبور',qty:1,xp:7,gold:3},{zone:'ironhollow',village:'روستای سنگ‌آهن',place:'میدان سنگ‌تراشان',title:'نمایش هنر سنگ',host:'دُرن سنگ‌تراش',desc:'سنگ‌تراشان قطعات کوچک و بی‌خطر را به نقش‌های یادبود تبدیل می‌کنند. معدن‌کاران برای خانواده‌ها صندلی می‌چینند و شاگردان آثارشان را به نمایش می‌گذارند.',dialogue:'دُرن می‌گوید: «سنگ سخت است، اما دست‌های همراه می‌توانند از آن یادگاری بسازند.»',reward:'cut_stone',item:'سنگ ساختمانی',qty:1,xp:7,gold:4},{zone:'city',village:'شهر خاکستر',place:'میدان برج ساعت',title:'بازارچه و موسیقی میدان',host:'تورِن استاد انجمن',desc:'بازرگانان غرفه‌های کوچک برپا کرده‌اند و نوازندگان محلی در میدان برج ساعت می‌نوازند. نگهبانان و مسافران کنار فواره جمع شده‌اند و خبرهای خوش چهار آبادی را با هم ردوبدل می‌کنند.',dialogue:'تورِن می‌گوید: «چهار آبادی، چهار خانه نیستند؛ یک خانواده‌اند.»',reward:'honey',item:'عسل طبیعی',qty:1,xp:8,gold:5}];return events[(day-1)%events.length];}
  function joinCommunityEvent(){const e=communityEventForDay(),p=state.worldPosition||{x:1500,y:1050},v=safeVillages.find(x=>x.id===e.zone),inside=v&&((p.x-v.cx)/v.rx)**2+((p.y-v.cy)/v.ry)**2<=1,day=state.worldClock?.day||1;state.communityEvents=state.communityEvents||{};if(!inside){notice='برای شرکت در «'+e.title+'» باید به '+e.village+' و '+e.place+' بروی.';render();return;}if(state.communityEvents[day]){notice='امروز در جشن شرکت کرده‌ای؛ رویداد بعدی فردا برگزار می‌شود.';render();return;}state.communityEvents[day]=true;state.communityEventZones=state.communityEventZones||{};state.communityEventZones[e.zone]=true;const it=state.inventory.find(x=>x.id===e.reward);if(it)it.qty+=e.qty;else state.inventory.push({id:e.reward,name:e.item,qty:e.qty});state.gold+=e.gold;grantPersonalQuestXp(e.xp);journal('رویداد اجتماعی «'+e.title+'» در '+e.village+': '+e.dialogue+' پاداش: '+e.qty+' '+e.item+'، '+e.gold+' سکه و '+e.xp+' تجربه.');msg(e.dialogue+' در جشن با اهالی گفت‌وگو کردی، به موسیقی و کارهای جمعی پیوستی و '+e.item+' دریافت کردی. '+e.gold+' سکه و '+e.xp+' تجربه نیز گرفتی.','رویدادهای اجتماعی');notice='در «'+e.title+'» شرکت کردی؛ '+e.item+'، '+e.gold+' سکه و '+e.xp+' تجربه دریافت شد.';save();render();}
  function tabContent(){if(activeTab==="hunt")return firstRegionView();if(activeTab==="regionmap")return firstRegionMapView();if(activeTab==="craft")return craftingView();if(activeTab==="dungeons")return dungeonView();if(activeTab==="safecompletion"||activeTab==="discoveries"){const found=state.landmarkDiscoveries||{},discovered=safeLandmarks.filter(m=>found[m.id]).length,events=state.communityEvents||{},zones=new Set(Object.keys(state.communityEventZones||{}));Object.keys(events).filter(k=>events[k]).forEach(k=>zones.add(['grain','rootwood','ironhollow','city'][(Math.max(1,Number(k))-1)%4]));const eventCount=zones.size,done=discovered===safeLandmarks.length&&['grain','rootwood','ironhollow','city'].every(z=>zones.has(z));const reward=!!state.safeRegionRewardClaimed;if(done&&!reward){state.safeRegionRewardClaimed=true;state.gold+=40;grantPersonalQuestXp(30);journal('منطقه آغازین امن به‌طور کامل اکتشاف شد؛ نشان پیمان چهار آبادی، ۴۰ سکه و ۳۰ تجربه دریافت شد.');msg('چهار آبادی و همه مکان‌های دیدنی را شناختی. اهالی نشان پیمان چهار آبادی را به تو می‌سپارند؛ ۴۰ سکه و ۳۰ تجربه نیز پاداش توست.','پیمان چهار آبادی');save();}return '<section class="panel"><div class="sect"><b>پایان ساخت منطقه آغازین امن</b><small>'+(done?'منطقه تکمیل شده':'پیشرفت اکتشاف و همراهی')+'</small></div><p class="muted">چهار آبادی، راه‌های پیوندی و مکان‌های آرام را کشف کن. این محدوده برای زندگی، گفت‌وگو و اکتشاف طراحی شده و دشمن یا نبردی در آن وجود ندارد.</p><div class="row"><span>مکان‌های دیدنی و پنهان</span><b>'+discovered+' / '+safeLandmarks.length+'</b></div><div class="row"><span>گردهمایی‌های اجتماعی در آبادی‌های متفاوت</span><b>'+eventCount+' / 4</b></div><div class="row"><span>سکونتگاه‌های امن</span><b>۴ / ۴</b></div><div class="row"><span>ساختمان‌ها و خدمات محلی</span><b>۲۵ / ۲۵</b></div><div class="row"><span>ساکنان ثبت‌شده</span><b>۲۶ / ۲۶</b></div><div class="row"><span>گذرگاه‌های پیرامونی بسته</span><b>'+safePerimeterGates.length+' / ۱۰</b></div><div style="height:9px;background:#211f25;border-radius:9px;overflow:hidden;margin:12px 0"><i style="display:block;height:100%;width:'+Math.min(100,(discovered/safeLandmarks.length*75+Math.min(4,eventCount)/4*25))+'%;background:#c7a66b"></i></div>'+safeLandmarks.map(m=>'<div class="row"><span>'+(found[m.id]?'✦ ':'◇ ')+esc(m.name)+'</span><b>'+(found[m.id]?'کشف‌شده':'در انتظار کشف')+'</b></div>').join('')+'<div class="row"><span>پاداش پیمان چهار آبادی</span><b>'+(done?'دریافت‌شده':'پس از کشف همه مکان‌ها و شرکت در چهار جشن')+'</b></div><p class="muted">مأموریت «پیمان چهار آبادی»، دو روایت فرعی، سرنخ‌های داخلی و گفت‌وگوهای ساکنان، محتوای روایی تکمیلی‌اند و برای دریافت نشان اجباری نیستند.</p></section>'; }if(activeTab==="community"){const e=communityEventForDay(),p=state.worldPosition||{x:1500,y:1050},v=safeVillages.find(x=>x.id===e.zone),inside=v&&((p.x-v.cx)/v.rx)**2+((p.y-v.cy)/v.ry)**2<=1,done=!!state.communityEvents?.[state.worldClock?.day||1];return '<section class="panel"><div class="sect"><b>زندگی اجتماعی چهار آبادی</b><small>روز '+Number(state.worldClock?.day||1)+'</small></div><p class="muted">هر روز یکی از چهار آبادی میزبان یک گردهمایی امن است. برنامه با روز جهان تغییر می‌کند و اهالی در آن نقش دارند.</p><article style="border:1px solid #8b7652;background:#292720;border-radius:13px;padding:15px;margin:10px 0"><small style="color:#d9bb83">رویداد امروز • '+esc(e.village)+'</small><h3 style="margin:8px 0;color:#ead3a8">'+esc(e.title)+'</h3><b>'+esc(e.place)+' • میزبان: '+esc(e.host)+'</b><p>'+esc(e.desc)+'</p><blockquote style="margin:10px 0;padding:10px;border-right:3px solid #b99a69;color:#d8c7a8;line-height:1.9">'+esc(e.dialogue)+'</blockquote><div class="row"><span>پاداش شرکت</span><b>'+e.qty+' '+esc(e.item)+' • '+e.gold+' سکه • '+e.xp+' تجربه</b></div><small style="display:block;color:#b8a78c;margin:10px 0">'+(done?'امروز در این رویداد شرکت کرده‌ای.':inside?'تو در محدوده '+esc(e.village)+' هستی و می‌توانی به جشن بپیوندی.':'برای شرکت باید به محدوده '+esc(e.village)+' بروی.')+'</small><button type="button" data-community-join '+(done?'disabled':'')+' style="width:100%;padding:12px;border:1px solid #c4a46d;border-radius:9px;background:'+(done?'#3a3833':'#9c7c4d')+';color:#fff">'+(done?'شرکت انجام شد':inside?'پیوستن به رویداد امروز':'نمایش راهنمای شرکت در رویداد')+'</button></article><div class="sect"><b>چرخه جشن‌ها</b><small>تکرار هر چهار روز</small></div>'+[{n:'کشتزار',t:'جشن نان تازه'},{n:'ریشه‌چوب',t:'شب فانوس‌های جنگلی'},{n:'سنگ‌آهن',t:'نمایش هنر سنگ'},{n:'شهر خاکستر',t:'بازارچه و موسیقی میدان'}].map((x,i)=>'<div class="row"><span>روز '+(i+1)+' • '+x.n+'</span><b>'+x.t+'</b></div>').join('')+'</section>'; }if(activeTab==="discoveries"){const found=state.landmarkDiscoveries||{},count=safeLandmarks.filter(m=>found[m.id]).length;return '<section class="panel"><div class="sect"><b>دفتر اکتشاف منطقه امن</b><small>'+count+' از '+safeLandmarks.length+' مکان کشف‌شده • شامل چهار مکان پنهان</small></div><div style="height:8px;background:#211f25;border-radius:9px;overflow:hidden;margin:10px 0 16px"><i style="display:block;height:100%;width:'+(count/safeLandmarks.length*100)+'%;background:#c7a66b"></i></div>'+safeLandmarks.map(m=>'<article style="border:1px solid #51463a;background:#29252a;border-radius:11px;padding:12px;margin:9px 0"><b style="color:#d8b88e">'+(found[m.id]?'✦ ':'◇ ')+esc(m.name)+'</b><p style="line-height:1.9;margin:7px 0 0">'+(found[m.id]?esc(m.note):'هنوز کشف نشده است؛ به این مکان برو و آن را بررسی کن.')+'</p></article>').join('')+'</section>';}if(activeTab==="reports"){const logs=state.actionHistory||[];return '<section class="panel"><div class="sect"><b>گزارش تعاملات</b><small>گفت‌وگو • خرید • مأموریت • هدیه</small></div><p class="muted">جزئیات پاسخ شخصیت‌ها و نتیجه کارهایی که پس از تأیید انجام داده‌ای، به ترتیب تازه‌ترین رویداد اینجا ثبت می‌شود.</p>'+(logs.length?logs.map(x=>'<article style="border:1px solid #51463a;background:#29252a;border-radius:11px;padding:12px;margin:9px 0"><div style="display:flex;justify-content:space-between;gap:8px"><b style="color:#d8b88e">'+esc(x.who||"گزارش بازی")+'</b><small style="color:#9d9290">روز '+(x.day||1)+'</small></div><p style="line-height:2;margin:8px 0 0">'+esc(x.text)+'</p></article>').join(''):'<div style="padding:22px;text-align:center;border:1px dashed #8c7956;border-radius:12px;color:#cfc2a7">هنوز تعاملی ثبت نشده است. پس از گفتگو، خرید یا انجام مأموریت، گزارش کامل اینجا نمایش داده می‌شود.</div>')+'</section>';}if(activeTab==="quests"){const personal=Object.entries(state.personalQuests||{}).map(([id,q])=>{const n=safeNPCs.find(x=>x.id===id);return {name:n?.name||id,q};});const rows=[];const rq=state.regionQuest;if(rq&&(rq.stage>0||rq.completed))rows.push('<article style="border:1px solid #756448;background:#292722;border-radius:12px;padding:14px;margin:10px 0"><b>پیمان چهار آبادی</b><span style="float:left;color:#d7bd86">'+(rq.completed?'تکمیل‌شده':'در جریان')+'</span><p>'+(rq.completed?'پیمان چهار آبادی را به پایان رسانده‌ای.':'مرحله '+rq.stage+' از ۵ • '+(rq.stage===1?'تعمیر چرخ آسیاب':rq.stage===2?'روشن‌کردن فانوس ریشه‌چوب':rq.stage===3?'ساخت بست آهنی':rq.stage===4?'تصمیم در نیایشگاه':'آغاز پیمان'))+'</p></article>');const lq=state.lanternQuest;if(lq&&(lq.stage>0||lq.completed))rows.push('<article style="border:1px solid #756448;background:#292722;border-radius:12px;padding:14px;margin:10px 0"><b>فانوس خاموش شمال</b><span style="float:left;color:#d7bd86">'+(lq.completed?'تکمیل‌شده':'در جریان')+'</span><p>'+(lq.completed?'فانوس شمالی دوباره روشن شده است.':lq.stage===1?'مرحله ۱ از ۳ • تهیه ۲ موم زنبور از مِل':lq.stage===2?'مرحله ۲ از ۳ • تهیه ۱ آب پاک از سِرا':'مرحله ۳ از ۳ • بازگشت به میرا')+'</p></article>');const oq=state.oreLedgerQuest;if(oq&&(oq.stage>0||oq.completed))rows.push('<article style="border:1px solid #756448;background:#292722;border-radius:12px;padding:14px;margin:10px 0"><b>دفتر گمشده معدن</b><span style="float:left;color:#d7bd86">'+(oq.completed?'تکمیل‌شده':'در جریان')+'</span><p>'+(oq.completed?'اختلاف دفتر معدن حل شده است.':oq.stage===1?'مرحله ۱ از ۳ • پرس‌وجو از دُرن':oq.stage===2?'مرحله ۲ از ۳ • تهیه ۲ سنگ‌آهن و گفت‌وگو با وِک':'مرحله ۳ از ۳ • بازگشت به وِس')+'</p></article>');personal.forEach(({name,q})=>{if(q.active||q.completed){const need=q.active?.qty||0,have=q.active?(state.inventory||[]).filter(x=>x.id===q.active.itemId).reduce((sum,x)=>sum+(x.qty||0),0):0,ready=!!q.active&&have>=need;rows.push('<article style="border:1px solid #756448;background:#292722;border-radius:12px;padding:14px;margin:10px 0"><b>مأموریت‌های شخصی • '+esc(name)+'</b><span style="float:left;color:#d7bd86">'+(q.active?'در جریان':q.completed+'/۱۰ تکمیل‌شده')+'</span><p>'+(q.active?'درخواست: '+esc(q.active.title)+'</p><div style="display:flex;justify-content:space-between;gap:8px;align-items:center;padding:10px;border-radius:9px;background:'+(ready?'#1e3828':'#3b2529')+';color:'+(ready?'#8fe0a5':'#ff8b91')+'"><b>'+esc(q.active.itemName)+' • '+have+' / '+need+'</b><strong>'+(ready?'آماده تکمیل ✓':'کمبود آیتم ✕')+'</strong></div>':'<p>'+q.completed+' مأموریت از ۱۰ مأموریت تکمیل شده است.')+'</article>');}});const d=state.dailyRequest;if(d)rows.push('<article style="border:1px solid #756448;background:#292722;border-radius:12px;padding:14px;margin:10px 0"><b>درخواست روزانه • '+esc(d.npcName)+'</b><span style="float:left;color:#d7bd86">'+(d.status==='active'?'در انتظار تحویل':d.status==='completed'?'تکمیل‌شده':'ثبت‌شده')+'</span><p>'+esc(d.qty+' '+d.itemName)+' • پاداش '+d.reward+' سکه</p></article>');return '<section class="panel"><div class="sect"><b>دفتر مأموریت‌ها</b><small>'+rows.length+' مأموریت ثبت‌شده</small></div><p class="muted">همه مأموریت‌هایی که پذیرفته‌ای یا در حال انجامشان هستی، اینجا نمایش داده می‌شوند.</p>'+(rows.length?rows.join(''):'<div style="padding:22px;text-align:center;border:1px dashed #8c7956;border-radius:12px;color:#cfc2a7">هنوز مأموریتی نپذیرفته‌ای. با ساکنان و استاد انجمن صحبت کن تا مأموریت بگیری.</div>')+'</section>';}if(activeTab==="skills")return renderSkillBook();if(activeTab==="character"){const c=state.character;return '<section class="panel"><div class="sect"><b>شخصیت</b><small>'+esc(c.rank)+'</small></div><h2>'+esc(c.name)+'</h2><p class="muted">'+esc(c.appearance)+'</p><div class="origin-card"><b>✦ '+esc(c.origin||"پیشینه ناشناخته")+'</b><p>'+esc(c.birth||"") +'</p></div><div class="specialization-card" style="border:1px solid #806b50;background:linear-gradient(145deg,#29242b,#1d2227);border-radius:13px;padding:14px;margin:14px 0"><div class="sect"><b>مسیر تخصصی • '+esc(c.specialization||((CLASS_DATA[c.archetype]||CLASS_DATA["جنگجو"]).specs[0]))+'</b><small>'+esc(c.archetype||"جنگجو")+' • '+esc(specializationProfile(c.archetype||"جنگجو",c.specialization||((CLASS_DATA[c.archetype]||CLASS_DATA["جنگجو"]).specs[0])).role)+'</small></div><p class="muted">۱۰ مهارت این تخصص به‌ترتیب در سطح‌های ۵ تا ۵۰، هر پنج سطح یک مهارت، به‌صورت خودکار آموخته می‌شوند:</p>'+specializationProfile(c.archetype||"جنگجو",c.specialization||((CLASS_DATA[c.archetype]||CLASS_DATA["جنگجو"]).specs[0])).skills.map((skill,i)=>'<div class="row"><span>✧ '+esc(skill)+'</span><b>'+(c.level>=[5,10,15,20,25,30,35,40,45,50][i]?'آموخته‌شده':'سطح '+[5,10,15,20,25,30,35,40,45,50][i])+'</b><small style="display:block;flex-basis:100%;line-height:1.8;color:#c7b99d">'+esc(specializationProfile(c.archetype||"جنگجو",c.specialization||((CLASS_DATA[c.archetype]||CLASS_DATA["جنگجو"]).specs[0])).details[i])+'</small></div>').join('')+'<small style="display:block;line-height:1.8;color:#c7b99d;margin-top:8px">با رسیدن به سطح تعیین‌شده، مهارت همان تخصص خودکار آموخته می‌شود. این نسخه زمان‌بندی یادگیری را برای هر ۴۰ تخصص یکسان اعمال می‌کند؛ برای ارتقا و مشاهده رتبه‌ها، دفتر مهارت‌ها را از منوی بازی باز کن؛ مهارت‌های فعال در نبرد قابل استفاده‌اند.</small></div><div class="stats">'+Object.entries({قدرت:effectiveCharacterStats().power,سرعت:effectiveCharacterStats().agility,استقامت:effectiveCharacterStats().endurance,سرزندگی:effectiveCharacterStats().vitality,هوش:effectiveCharacterStats().intellect,ادراک:effectiveCharacterStats().perception,شانس:effectiveCharacterStats().luck,ایمان:effectiveCharacterStats().faith}).map(x=>'<div><small>'+x[0]+'</small><b>'+x[1]+'</b></div>').join('')+'</div><p>تجربه: '+c.xp+' / '+xpRequiredForLevel(c.level)+' • ضریب رشد هر سطح: ×۱٫۵</p><p>سکه: '+state.gold+'</p><div class="sect" style="margin-top:18px"><b>وسایل همراه</b><small>موجودی شخصیت</small></div>'+state.inventory.map(i=>'<div class="row"><span>◈ '+esc(i.name)+'</span><b>× '+i.qty+'</b></div>').join('')+'<div class="row"><span>سکه</span><b>'+state.gold+' ◉</b></div></section>';}if(activeTab==="inventory"){const c=state.character,equipped=state.equipmentSlots||{},bonus=equipmentBonuses();return '<section class="panel"><div class="sect"><b>تجهیزات شخصیت</b><small>'+esc(c.archetype||"جنگجو")+' • '+esc(c.specialization||"")+'</small></div><button type="button" data-open-recipes style="width:100%;min-height:48px;margin:8px 0;border:1px solid #b99a65;border-radius:10px;background:linear-gradient(135deg,#332638,#201c27);color:#e8d1a4;font-weight:700">📜 دستور ساخت‌ها • دفتر دستورهای کشف‌شده</button><div class="row"><span>سطح بازیکن</span><b>'+c.level+'</b></div><div class="row"><span>سکه</span><b>'+state.gold+' ◉</b></div><div class="sect" style="margin-top:15px"><b>جایگاه‌های مجهز</b><small>۱۰ اسلات</small></div>'+EQUIPMENT_SLOTS.map(([slot,label])=>{const it=equipped[slot];return '<article class="row"><span>'+label+'</span><b>'+(it?esc(it.name)+' • سطح آیتم '+it.itemLevel+' • دوام '+(it.durability??100)+'/100 • +'+(it.upgradeLevel||0):'خالی')+'</b>'+(it?'<small style="display:block;flex-basis:100%;line-height:1.8;color:#c7b99d">'+esc(it.description||"تجهیز کلاس "+(it.className||c.archetype))+'<br>اثرها: '+esc(effectSummary(it.effects))+'</small><button type="button" data-unequip-slot="'+slot+'">درآوردن و بازگرداندن به کیف</button><button type="button" data-delete-equipped-slot="'+slot+'">حذف دائمی</button>':'')+'</article>';}).join('')+'<div class="sect" style="margin-top:18px"><b>آمار افزوده تجهیزات</b><small>اثر مجموع آیتم‌های مجهز</small></div>'+Object.entries({قدرت:bonus.power,چابکی:bonus.agility,استقامت:bonus.endurance,سرزندگی:bonus.vitality,هوش:bonus.intellect,ادراک:bonus.perception,شانس:bonus.luck,ایمان:bonus.faith,دفاع:bonus.defense,سلامتی:bonus.hp,مانا:bonus.mp,استقامت_حرکتی:bonus.stamina,ضربه_بحرانی:bonus.crit}).filter(x=>x[1]>0).map(x=>'<div class="row"><span>'+x[0]+'</span><b>+'+x[1]+'</b></div>').join('')+'<div class="sect" style="margin-top:18px"><b>وسایل همراه</b><small>تجهیزات خریداری‌شده و منابع</small></div>'+state.inventory.map(i=>'<article class="row"><span>◈ '+esc(i.name)+'</span><b>× '+i.qty+(i.itemLevel?' • سطح آیتم '+i.itemLevel+' • '+esc(i.quality||"معمولی"):'')+'</b>'+((i.description||CONSUMABLE_ITEMS[i.id])?'<small style="display:block;flex-basis:100%;line-height:1.8;color:#c7b99d">'+esc(i.description||CONSUMABLE_ITEMS[i.id].description)+(i.effects?'<br>اثرها: '+esc(effectSummary(i.effects)):CONSUMABLE_ITEMS[i.id]?'<br>اثر مصرف: '+esc(effectSummary(CONSUMABLE_ITEMS[i.id].effects)):'')+'</small>':'')+(CONSUMABLE_ITEMS[i.id]?'<button type="button" data-use-item="'+esc(i.id)+'">مصرف آیتم</button>':'')+(i.slot?'<button type="button" data-equip-item="'+esc(i.id)+'" '+((c.level||1)<((i.itemLevel||1)<=1?1:(i.requiredPlayerLevel||5))?'disabled':'')+'>تجهیز در جایگاه '+esc(EQUIPMENT_SLOTS.find(x=>x[0]===i.slot)?.[1]||i.slot)+'</button>':'')+'<button type="button" data-delete-item="'+esc(i.id)+'">حذف از کیف</button></article>').join('')+'</section>';} if(activeTab==="recipes"){const known=knownRecipeIds(),current=state.character.archetype||"جنگجو",recipes=CLASS_CRAFTING_RECIPES.filter(r=>known.includes(r.id)&&r.className===current).sort((a,b)=>a.tier-b.tier),materialIds=[...new Set(recipes.flatMap(r=>r.materials.map(m=>m.id)))];return '<section class="panel"><button type="button" data-back-inventory style="margin-bottom:12px">← بازگشت به کیف</button><div class="sect"><b>دستور ساخت‌ها</b><small>'+recipes.length+' دستور کشف‌شده • کلاس '+esc(current)+'</small></div><p class="muted">هر دستور شامل جزئیات تجهیز، مواد لازم و تعداد موجود در کیف است. مقدار کافی سبز و مقدار ناکافی یا ماده نداشته قرمز نمایش داده می‌شود.</p><div class="sect"><b>موجودی مواد لازم</b><small>سبز: موجود • قرمز: ناموجود</small></div>'+materialIds.map(id=>{const mat=REGION_MATERIALS[id],qty=materialInventoryCount(id);return '<div class="row"><span>'+esc(mat?.name||id)+'</span><b style="color:'+(qty>0?"#55d98a":"#ff6666")+'">'+qty+' عدد</b></div>';}).join("")+recipes.map(r=>'<article style="border:1px solid #786746;background:#29252a;border-radius:12px;padding:12px;margin:10px 0"><b>'+esc(r.output.name)+'</b><small style="display:block;color:#d0bd91">'+esc(r.className)+' • '+r.slotLabel+' • سطح ساخت '+r.tier+'</small><p style="line-height:1.8;color:#c8bdab">'+esc(r.output.description)+'</p><b>مواد موردنیاز</b>'+r.materials.map(m=>{const qty=materialInventoryCount(m.id),enough=qty>=m.qty;return '<div class="row"><span>'+esc(REGION_MATERIALS[m.id]?.name||m.id)+' <small style="display:block;color:#aebd9d">منبع: '+esc(REGION_MATERIALS[m.id]?.source||"منطقه کشف‌شده")+'</small></span><b style="color:'+(enough?"#55d98a":"#ff6666")+'">'+qty+' / '+m.qty+'</b></div>';}).join("")+'<div class="row"><span>هزینه ساخت</span><b>'+r.gold+' سکه</b></div><p class="muted" style="margin-top:10px">برای ساخت این تجهیز، دستور و مواد کافی را نزد آهنگر شهر خاکستر ببر.</p></article>').join("")+(recipes.length?"":'<p class="muted">هنوز دستور ساختی برای کلاس فعلی کشف نکرده‌ای. با شکار هیولاها یا جست‌وجوی دانجن‌ها و خرابه‌ها دستور پیدا کن.</p>')+'</section>';}if(activeTab==="map")return '<section class="panel atlas-panel"><div class="sect"><b>نقشه کلان جهان ETRANOM</b><small>اطلس داده‌محور • شبکه مرجع مقیاس‌دار، نه ژئودتیک</small></div>'+renderWorldAtlas()+'<div class="world-map"><svg viewBox="0 0 760 390" role="img" aria-label="نقشه شماتیک جهان با پنج قاره نقش‌محور"><defs><linearGradient id="worldsea" x2="0" y2="1"><stop stop-color="#203b43"/><stop offset="1" stop-color="#101e29"/></linearGradient><linearGradient id="landA" x2="1" y2="1"><stop stop-color="#b6a078"/><stop offset="1" stop-color="#68765d"/></linearGradient><filter id="worldshadow"><feGaussianBlur stdDeviation="7"/></filter></defs><rect width="760" height="390" fill="url(#worldsea)"/><g fill="#d4c49a" opacity=".18"><circle cx="70" cy="55" r="2"/><circle cx="680" cy="60" r="2"/><circle cx="590" cy="310" r="2"/><circle cx="210" cy="340" r="2"/><circle cx="420" cy="45" r="2"/></g><g fill="#000" opacity=".3" filter="url(#worldshadow)" transform="translate(0 8)"><path d="M65 88Q110 35 190 62L245 92 229 155 185 180 140 165 92 190 48 147Z"/><path d="M278 58Q344 25 405 65L430 120 390 168 320 155 280 112Z"/><path d="M255 210Q310 170 370 205L395 278 350 350 290 330 260 275Z"/><path d="M450 150Q520 105 610 145L680 205 640 270 560 285 500 245 455 205Z"/><path d="M600 45Q650 20 710 55L725 105 680 130 625 105Z"/></g><g fill="url(#landA)" stroke="#d6c59a" stroke-width="3"><path d="M65 82Q110 35 190 62L245 92 229 155 185 180 140 165 92 190 48 147Z"/><path d="M278 58Q344 25 405 65L430 120 390 168 320 155 280 112Z"/><path d="M255 210Q310 170 370 205L395 278 350 350 290 330 260 275Z"/><path d="M450 150Q520 105 610 145L680 205 640 270 560 285 500 245 455 205Z"/><path d="M600 45Q650 20 710 55L725 105 680 130 625 105Z"/></g><g fill="#e5d6b5" font-family="Tahoma" font-size="17" text-anchor="middle" paint-order="stroke" stroke="#26332e" stroke-width="4"><text x="145" y="120">قلب تمدن‌ها</text><text x="355" y="100">باستانی</text><text x="325" y="270">وحشی</text><text x="565" y="205">جادویی</text><text x="665" y="82">دوردست</text></g><g fill="#d9c79b" opacity=".8"><path d="M110 225q20-15 40 0t40 0" fill="none" stroke="#d9c79b" stroke-width="2"/><path d="M470 320q22-18 44 0t44 0" fill="none" stroke="#d9c79b" stroke-width="2"/><path d="M530 65q15-10 30 0t30 0" fill="none" stroke="#d9c79b" stroke-width="2"/></g><g fill="#e7d8b8" font-family="Tahoma" font-size="12"><text x="18" y="370">اقیانوس‌ها • دریاهای داخلی • مجمع‌الجزایر</text><text x="650" y="370">شمال ↑</text></g></svg><div class="world-map-note">پنج قاره نقش‌محور؛ مرزها، نام‌ها و مقیاس نهایی هنوز در مرحله جهان‌سازی‌اند.</div></div><div class="world-layers"><div><b>◈ دریاها و اقیانوس‌ها</b><small>دریاهای داخلی، اقیانوس‌های پهناور و مجمع‌الجزایر</small></div><div><b>◈ ژرفای جهان</b><small>جهان زیرزمینی چندلایه و قلمروهای پنهان</small></div><div><b>◈ سرزمین‌های ناشناخته</b><small>مناطق دوردست و فراطبیعی با خطر مستقل از سطح بازیکن</small></div></div><div class="sect" style="margin-top:18px"><b>اطلس محلی شهر خاکستر</b><small>شمال ↑ • مکان‌های کشف‌شده</small></div><div class="atlas"><svg class="atlas-svg" viewBox="0 0 760 560" role="img" aria-label="نقشه مصور منطقه شهر خاکستر"><defs><linearGradient id="parch" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#c7b58b"/><stop offset=".48" stop-color="#9e9a70"/><stop offset="1" stop-color="#596b55"/></linearGradient><linearGradient id="sea" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#243e43"/><stop offset="1" stop-color="#172c32"/></linearGradient><pattern id="papergrain" width="17" height="17" patternUnits="userSpaceOnUse"><circle cx="3" cy="4" r="1" fill="#342e25" opacity=".12"/><circle cx="13" cy="12" r=".8" fill="#fff" opacity=".12"/></pattern><filter id="shadow"><feGaussianBlur stdDeviation="5"/></filter></defs><rect width="760" height="560" rx="18" fill="url(#sea)"/><path d="M0 0H760V560H0Z" fill="url(#papergrain)"/><path d="M35 90L112 42 210 55 282 28 375 62 467 45 545 88 674 73 731 156 704 260 741 342 676 455 560 503 463 474 365 535 266 492 165 520 76 438 49 326 18 218Z" fill="url(#parch)" stroke="#d2c39a" stroke-width="5"/><path d="M35 90L112 42 210 55 282 28 375 62 467 45 545 88 674 73 731 156 704 260 741 342 676 455 560 503 463 474 365 535 266 492 165 520 76 438 49 326 18 218Z" fill="url(#papergrain)"/><path d="M88 155Q170 92 246 128T398 116Q490 94 602 150L655 235Q565 271 505 238T365 263Q247 296 151 253Z" fill="#69795e" opacity=".85"/><path d="M65 340Q145 287 224 327T376 330Q476 298 560 352L623 435 514 477 400 452 302 488 190 451 102 432Z" fill="#344b3c" opacity=".8"/><path d="M87 175Q170 220 251 199T410 210Q510 225 650 330" fill="none" stroke="#6d9a9b" stroke-width="22" opacity=".85"/><path d="M87 175Q170 220 251 199T410 210Q510 225 650 330" fill="none" stroke="#b2c9b2" stroke-width="3" opacity=".7"/><path d="M270 40L315 92 292 143 350 182 333 246 385 291 369 355 422 410" fill="none" stroke="#6b5d4b" stroke-width="9" opacity=".7"/><path d="M270 40L315 92 292 143 350 182 333 246 385 291 369 355 422 410" fill="none" stroke="#d0bd91" stroke-width="2" stroke-dasharray="8 9"/><g fill="#d0c29a" stroke="#4b5140" stroke-width="3" opacity=".95"><path d="M80 90l28-32 24 34-26-8Z"/><path d="M124 84l31-41 30 42-32-10Z"/><path d="M170 102l26-34 25 39-28-10Z"/><path d="M500 93l25-33 24 36-25-8Z"/><path d="M540 112l31-42 29 45-32-12Z"/><path d="M590 130l24-31 27 37-28-10Z"/></g><g fill="#263a31" opacity=".85"><path d="M90 380l17-45 17 45Zm30 17 18-50 19 50Zm37-6 19-51 18 51Zm35 20 17-43 18 43Zm32-11 20-53 20 53Zm31 29 17-45 18 45Z"/></g><g fill="none" stroke="#b7a77c" stroke-width="3" opacity=".75"><path d="M145 145q45-30 85 0t90-8"/><path d="M480 390q35-35 75-12t64-8"/><path d="M490 420q40-28 78-8"/></g><g class="atlas-label"><text x="122" y="60">کوهستان مه‌آلود</text><text x="493" y="58">قله‌های شکسته</text><text x="85" y="465">جنگل سوخته</text><text x="525" y="470">باتلاق خاموش</text><text x="350" y="145">رود نقره‌ای</text><text x="365" y="520">دشت خاکستر</text></g><path d="M205 215Q260 188 330 210T455 275Q520 325 580 390" fill="none" stroke="#e8d6a8" stroke-width="5" stroke-dasharray="5 10" stroke-linecap="round"/><g class="atlas-pin" data-map="intro" tabindex="0" role="button" aria-label="دروازه خاکستر" transform="translate(205 215)"><circle r="20" class="pin-halo"/><circle r="9" class="pin-town"/><text x="-12" y="-25">دروازه خاکستر</text></g><g class="atlas-pin" data-map="city" tabindex="0" role="button" aria-label="شهر خاکستر" transform="translate(330 210)"><circle r="24" class="pin-halo"/><path d="M-10 7V-5L0-14 10-5V7Z" class="pin-town"/><text x="0" y="-30" text-anchor="middle">شهر خاکستر</text></g><g class="atlas-pin" data-map="inn" tabindex="0" role="button" aria-label="مسافرخانه" transform="translate(375 244)"><circle r="12" class="pin-halo"/><path d="M-7 5V-4L0-10 7-4V5Z" class="pin-settlement"/><text x="15" y="3">مسافرخانه</text></g><g class="atlas-pin" data-map="market" tabindex="0" role="button" aria-label="بازار" transform="translate(390 185)"><circle r="12" class="pin-halo"/><path d="M-8 4L-6-5H6L8 4Z" class="pin-settlement"/><text x="15" y="3">بازار</text></g><g class="atlas-pin" data-map="forest" tabindex="0" role="button" aria-label="جنگل سوخته" transform="translate(580 390)"><circle r="22" class="pin-halo"/><path d="M0-14L-12 8H12Z" class="pin-wild"/><text x="0" y="31" text-anchor="middle">جنگل سوخته</text></g><g class="atlas-pin '+(state.flags.ruinsSeen?'':'pin-locked')+'" data-map="ruins" tabindex="0" role="button" aria-label="ویرانه زیر ریشه‌ها" transform="translate(635 440)"><circle r="18" class="pin-halo"/><path d="M-10 8L-8-8 0-14 8-8 10 8Z" class="pin-ruin"/><text x="0" y="32" text-anchor="middle">'+(state.flags.ruinsSeen?'ویرانه زیر ریشه‌ها':'ناشناخته؟')+'</text></g><g transform="translate(690 55)" class="atlas-compass"><circle r="28"/><path d="M0-20L7 0 0 20-7 0Z"/><text x="0" y="-35" text-anchor="middle">شمال</text></g><text x="25" y="535" class="atlas-scale">اطلس محلی • طرح اکتشافی</text></svg><div class="atlas-key"><span><i class="key-town"></i> شهر و آبادی</span><span><i class="key-wild"></i> طبیعت</span><span><i class="key-ruin"></i> ویرانه</span><span>خط نقطه‌چین: مسیر</span></div></div><div class="atlas-current">موقعیت فعلی: <b>'+esc(state.location)+'</b></div><p class="muted">برای سفر، نشان یک مکان را لمس کن. مناطق پنهان تا زمان کشف در دسترس نیستند.</p></section>';if(activeTab==="cosmos")return '<section class="panel cosmos-panel"><div class="sect"><b>دفتر کیهان‌شناسی</b><small>ETRANOM • لایه بنیادین هستی</small></div><p class="muted">این دفتر فقط دانسته‌های ثبت‌شده در مرجع جهان را قطعی نمایش می‌دهد. بخش‌های حل‌نشده عمداً به‌عنوان راز یا قانون قطعی جعل نشده‌اند.</p><div class="cosmos-origin"><small>پیش از جهان‌های شناخته‌شده</small><h3>مبدأ نامعلوم</h3><p>ماهیت مبدأ، توالی پیدایش هستی و نسبت دقیق «اصل تمایز» با آغاز کیهان هنوز در مرجع قطعی تثبیت نشده است.</p><span>وضعیت: نیازمند تثبیت در کیهان‌نامه</span></div><div class="cosmos-force-grid"><article class="cosmos-force abyss"><div class="cosmos-symbol">◉</div><small>ABYSS • آبیس</small><h3>ژرفا، پایان و سقوط</h3><p>نیروی پایان، رنج و فروپاشی؛ هر چیزی که به آن نزدیک شود به‌سوی زوال و نابودی کشیده می‌شود.</p><blockquote>«هر چیزی که آغاز شده، می‌تواند به پایان برسد.»</blockquote><b>حوزه‌ها</b><p>مرگ، زوال، سقوط، تاریکی، انقراض، فرسایش، فروپاشی روح و پایان چرخه‌ها.</p></article><article class="cosmos-force nothing"><div class="cosmos-symbol">○</div><small>NOTHINGNESS • نیستی</small><h3>عدم مطلق، خلأ و فقدان</h3><p>با خود مفهوم وجود سروکار دارد؛ نه صرفاً نابودکردن، بلکه نفی امکان یا معنای بودن.</p><blockquote>«چیزی وجود ندارد که نیازمند وجود داشتن باشد.»</blockquote><b>حوزه‌ها</b><p>خلأ، سکوت مطلق، نبود زمان و مکان، محوشدگی، بی‌هویتی، فقدان و بی‌معنایی.</p></article><article class="cosmos-force chaos"><div class="cosmos-symbol">⟲</div><small>CHAOS • آشوب</small><h3>بی‌ثباتی، تناقض و تغییر</h3><p>نیروی بی‌ثباتی و دگرگونی؛ نظم را می‌شکند و هیچ شکل یا وضعیتی را تغییرناپذیر نمی‌داند.</p><blockquote>«هیچ‌چیزی مجبور نیست همان چیزی باقی بماند که هست.»</blockquote><b>حوزه‌ها</b><p>هرج‌ومرج، تصادف، تناقض، جهش، توهم، فساد، بی‌قاعدگی و احتمالات متغیر.</p></article></div><div class="cosmos-compare"><b>مرز سه حقیقت</b><div class="row"><span>آبیس</span><strong>پایانِ چیزی که وجود دارد</strong></div><div class="row"><span>نیستی</span><strong>فقدانِ خودِ وجود و معنا</strong></div><div class="row"><span>آشوب</span><strong>بی‌ثباتیِ شکل و نظم</strong></div><p class="muted">این سه نیرو در متن مرجع از خیر و شر و حتی از مفاهیمی مانند زندگی، مرگ، زمان و مکان بنیادی‌تر توصیف شده‌اند؛ بااین‌حال سازوکار دقیق اثرگذاری آن‌ها بر قوانین جهان هنوز مشخص نشده است.</p></div><div class="cosmos-laws"><div class="sect"><b>هشت قانون بنیادین هستی</b><small>فهرست قطعی هنوز ثبت نشده</small></div><p>هیچ نام، تعریف یا اثر اجرایی برای هشت قانون در منابع بررسی‌شده پیدا نشد. این جایگاه‌ها تا زمان تثبیت کیهان‌نامه بسته می‌مانند و به‌صورت تصادفی پر نمی‌شوند.</p><div class="law-seals">'+Array.from({length:8},(_,i)=>'<div><span>۰'+(i+1)+'</span><b>مهر قانون</b><small>در انتظار تعریف مرجع</small></div>').join('')+'</div></div><div class="cosmos-boundary"><b>حدود دانسته‌های فعلی</b><p>چگونگی پیدایش زمان، مکان، ماده، انرژی، روح، حیات و مرگ؛ ساختار لایه‌های چندجهانی؛ و نسبت دقیق سه نیرو با خدایان و قلمروهای الهی هنوز در این دفتر به‌عنوان قانون قطعی تعریف نشده‌اند.</p><small>این بخش‌ها تا زمان تدوین مرجع نهایی، از تغییر آمار، جادو، مبارزه و ذخیره شخصیت جلوگیری می‌کنند.</small></div></section>';if(activeTab==="ranks")return '<section class="panel rank-panel"><div class="sect"><b>نردبان رده‌های هستی</b><small>رده فعلی: '+esc(state.character.rank)+'</small></div><p class="muted">رده‌ها مسیر تکامل موجودات را نشان می‌دهند؛ ضرایب قدرت نبرد از کیفیت آمار، منابع و مهارت‌ها مستقل‌اند.</p><div class="rank-list">'+[["⚪","معمولی",1],["🟢","غیرمعمولی",6],["🔵","کمیاب",12],["🟣","نایاب",20],["🟠","افسانه‌ای",30],["🔴","اسطوره‌ای",45],["☀️","الهی",60],["💠","فراالهی",80]].map((r,i)=>'<div class="rank-row '+(String(state.character.rank).includes(r[1])?"current":"")+'"><span class="rank-symbol">'+r[0]+'</span><div><b>'+r[1]+'</b><small>'+(i===6?"رده تکاملی؛ فانی نیز می‌تواند به آن برسد.":i===7?"رده پنهان و رازآلود جهان.":"مرحله "+(i+1)+" از مسیر رده‌ها")+'</small></div><strong>×'+r[2]+'</strong></div>').join('')+'</div><div class="rank-lore"><b>قواعد بنیادین رده الهی</b><p>قلمرو الهی می‌تواند کسب، گسترش یا تصاحب شود؛ اما شرط الهی‌شدن نیست. خدایان آثار قوانین بنیادین را در قلمرو خود دست‌کاری می‌کنند، نه خود قوانین را.</p></div></section>';if(activeTab==="residents")return '<section class="panel"><div class="sect"><b>دفتر ساکنان منطقه امن</b><small>'+safeNPCs.length+' شخصیت ثبت‌شده</small></div>'+safeVillages.map(v=>'<section class="resident-zone"><h3>'+esc(v.name)+'</h3>'+safeNPCs.filter(n=>n.zone===v.id).map(n=>'<article class="resident-card"><b>'+esc(n.name)+'</b><span>'+esc(n.title)+' • '+esc(n.role)+'</span><p>'+esc(n.personality)+'؛ هدف: '+esc(n.goal)+'</p><small>دیالوگ آغازین: «'+esc(n.dialogue)+'»</small></article>').join('')+'</section>').join('')+'</section>';if(activeTab==="settings")return '<section class="panel"><div class="sect"><b>تنظیمات</b><small>مدیریت ماجراجویی</small></div><div class="row"><span>شخصیت فعال</span><b>'+esc(state.character.name)+'</b></div><div class="row"><span>موقعیت فعلی</span><b>'+esc(state.location)+'</b></div><p class="muted">از این بخش می‌توانی ماجراجویی فعلی را برای همیشه از ذخیره شخصی این بازی پاک کنی و با ساخت شخصیتی تازه از نو آغاز کنی.</p><div class="delete-card"><b>⚠ حذف کامل شخصیت</b><p>این عملیات شخصیت، موجودی، مأموریت‌ها، ژورنال و تمام پیشرفت ذخیره‌شده را از ذخیره شخصی بازی پاک می‌کند. فقط پس از تأیید نهایی انجام می‌شود و قابل بازگشت نیست.</p><button type="button" class="delete-character" data-restart>حذف شخصیت و تمام پیشرفت‌ها</button><small>اگر حذف ذخیره از سوی محیط بازی پشتیبانی نشود، هیچ داده‌ای پاک نخواهد شد.</small></div><div class="delete-card" style="margin-top:14px;border-color:#8b7652"><b>خروج از حساب</b><p>با خروج، فقط نشست ورود این دستگاه بسته می‌شود؛ شخصیت و پیشرفت بازی حذف نخواهد شد.</p><button type="button" class="delete-character" data-account-signout style="background:#44334b;border-color:#9c78ad">خروج از حساب</button></div></section>';if(activeTab==="story")return story();if(activeTab==="journal")return '<section class="panel"><div class="sect"><b>ژورنال</b><small>یادداشت‌های سفر</small></div>'+state.journal.map(x=>'<div class="entry">✧ '+esc(x)+'</div>').join('')+'</section>';return story();}
  function renderCreator(){root.innerHTML='<div class="shell landing-shell"><header class="brand"><div class="mark">✦</div><div><h1>ETRANOM</h1><small>سرزمین‌های بی‌کران</small></div><span class="brand-edition">CHRONICLES OF THE VEIL</span></header><section class="cinema"><div class="cinema-sky"><i class="cinema-moon"></i><i class="cinema-orbit"></i><i class="spire spire-a"></i><i class="spire spire-b"></i><i class="spire spire-c"></i><i class="cinema-mountains"></i><i class="cinema-ruins"></i></div><div class="cinema-shade"></div><div class="cinema-copy"><small class="gold-kicker">✧ فراتر از مرزهای شناخته‌شده ✧</small><h2>جهانی در آستانه<br><em>بیداری</em></h2><p>در سرزمین‌هایی که نامشان از یاد رفته، سرنوشت هنوز نوشته نشده است. این جهان به انتخاب تو پاسخ خواهد داد.</p><div class="cinema-rule"><i></i><span>THE WORLD REMEMBERS</span><i></i></div></div><div class="cinema-index">I <span>·</span> ETERNITY</div></section><div class="landing-intro"><span>منطقه آغازین • منطقه امن</span><b>سفر از شهر خاکستر آغاز می‌شود؛ سه روستا در مسیرهای امن پیرامون آن قرار دارند.</b><small>شهر خاکستر • کشتزار • ریشه‌چوب • سنگ‌آهن</small></div><form id="creator" class="panel creator-panel"><div class="creator-heading"><div><small class="gold-kicker">CREATE YOUR DESTINY</small><h3>هویت خود را برگزین</h3></div><span>✧</span></div><label>نام شخصیت<input name="name" maxlength="24" placeholder="نامی برای افسانه‌ات" required></label><div class="creator-rule"><span>✧</span><div><b>سرنوشت آغازین</b><small>نژاد، تبار، پیشینه، جایگاه و محل آغاز به‌صورت روایی و تصادفی تعیین می‌شوند؛ این ویژگی‌ها قابل ویرایش نیستند.</small></div><em>SEALED</em></div><label>کلاس آغازین<select name="archetype">'+Object.keys(CLASS_DATA).map(n=>'<option>'+esc(n)+'</option>').join('')+'</select></label><label>تخصص آغازین<select name="specialization">'+(CLASS_DATA["جنگجو"].specs.map(n=>'<option>'+esc(n)+'</option>').join(''))+'</select></label><label>توصیف ظاهر<textarea name="appearance" maxlength="180" rows="3" placeholder="چهره، مو، چشم، پوشش، زره و ویژگی‌های ظاهری شخصیتت..."></textarea><small class="field-hint">تنها ظاهر شخصیت را توصیف کن؛ ویژگی‌های ذاتی و توانایی‌ها از قوانین جهان تعیین می‌شوند.</small></label><button type="submit" class="primary">آغاز ماجراجویی ←</button><small class="form-error" role="alert" aria-live="polite"></small></form><p class="foot">۸۰٪ روایت و متن • ۲۰٪ عناصر بصری و تعاملی</p></div>';const form=root.querySelector("#creator");const classSelect=form.querySelector('[name="archetype"]'),specSelect=form.querySelector('[name="specialization"]');const updateSpecs=()=>{const specs=(CLASS_DATA[classSelect.value]||CLASS_DATA["جنگجو"]).specs;specSelect.innerHTML=specs.map(n=>'<option>'+esc(n)+'</option>').join('');};classSelect.addEventListener("change",updateSpecs);updateSpecs();const begin=e=>{e.preventDefault();if(form.dataset.started==="1")return;form.dataset.started="1";const button=form.querySelector("button.primary");if(button){button.disabled=true;button.textContent="در حال آغاز...";}try{createCharacter(form);}catch(err){form.dataset.started="";if(button){button.disabled=false;button.textContent="آغاز ماجراجویی ←";}const box=form.querySelector(".form-error");if(box)box.textContent="شروع بازی انجام نشد؛ دوباره تلاش کن." ;}};form.addEventListener("submit",begin);form.querySelector("button.primary").addEventListener("click",begin);}
  function renderEdit(){root.innerHTML='<div class="shell"><header class="brand"><div class="mark">E</div><div><h1>ETRANOM</h1><small>سرزمین‌های بی‌کران</small></div></header><section class="hero"><small>پیش‌نمایش سازنده</small><h2>RPG متنی فانتزی تاریک</h2><p>روایت، دیالوگ، انتخاب و اقدام آزاد هسته بازی هستند. در حالت Play ماجراجویی را آغاز کن.</p><b>☾</b></section><section class="panel"><h3>نسخه نخست</h3><div class="row"><span>شخصیت‌سازی</span><b>آماده</b></div><div class="row"><span>روایت و اقدام آزاد</span><b>آماده</b></div><div class="row"><span>مبارزه نوبتی</span><b>آماده</b></div><div class="row"><span>نقشه و ژورنال</span><b>آماده</b></div><div class="row"><span>ذخیره پیشرفت</span><b>Astrocade</b></div><p class="muted">برای تجربه بازی، حالت Play را انتخاب کن.</p></section></div>';}
